def lucas(n):
    if n == 0:
        return 2
    elif n == 1:
        return 1
    else:
        a, b = 2, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

L_100 = lucas(100)
print(f"L_100: {L_100}")

def fibonacci(n):
    if n <= 1:
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

# Generate F_2 through F_125
D = {}
for k in range(2, 126):
    D[k] = fibonacci(k)

# Check the magnitude of the largest difference
f_125 = D[125]
print(f"F_125 has {len(str(f_125))} digits.")
print(f"F_2 = {D[2]}")

